set search_path = naashir, extensions;

-- Free-plan guest limit for the categories added in 0007.
--
-- Identical to the function in 0001_init.sql except for the list of "big"
-- event types, which gains hair_cutting, reunion and corporate. Every other
-- type, including the new baby_shower / engagement / anniversary /
-- housewarming, falls through to the small limit.
--
-- Must match freeGuestLimit in src/lib/event-types.ts for every type;
-- scripts/verify-db.ts asserts that against a real database.
create or replace function naashir.enforce_rsvp_limit()
returns trigger
language plpgsql
as $$
declare
  v_event naashir.events%rowtype;
  v_limit int;
  v_count int;
begin
  select * into v_event from naashir.events where id = new.event_id;

  if v_event.is_paid then
    return new;
  end if;

  if v_event.event_type in ('wedding', 'graduation', 'hair_cutting', 'reunion', 'corporate') then
    v_limit := 100;
  else
    v_limit := 10;
  end if;

  select count(*) into v_count from naashir.rsvps where event_id = new.event_id;

  if v_count >= v_limit then
    raise exception 'guest_limit_reached' using errcode = 'P0001';
  end if;

  return new;
end;
$$;
